CREATE TABLE "users" (
    "id" SERIAL,
    "username" VARCHAR(100),
    "password" VARCHAR(100),
    "email" VARCHAR(100),
    "role" VARCHAR(50),
    PRIMARY KEY ("id")
);

CREATE TABLE "products" (
    "id" SERIAL,
    "name" VARCHAR(100),
    "description" TEXT,
    "category" VARCHAR(50),
    "price" DECIMAL(10, 2),
    "image_url" VARCHAR(255),
    PRIMARY KEY ("id")
);

CREATE TABLE "orders" (
    "id" SERIAL,
    "user_id" INT,
    "product_id" INT,
    "quantity" INT,
    "total_price" DECIMAL(10, 2),
    "status" VARCHAR(50),
    PRIMARY KEY ("id")
);

CREATE TABLE "order_history" (
    "id" SERIAL,
    "user_id" INT,
    "order_id" INT,
    "order_date" TIMESTAMP,
    PRIMARY KEY ("id")
);

CREATE TABLE "cart" (
    "id" SERIAL,
    "user_id" INT,
    "product_id" INT,
    "quantity" INT,
    PRIMARY KEY ("id")
);

